'use client';

import React, { useEffect, useRef, useState } from 'react';
import { db } from '@/lib/firebase';
import {
  doc,
  getDoc,
  updateDoc,
  arrayUnion,
  setDoc,
  onSnapshot,
  collection,
  addDoc,
  query,
  orderBy,
} from 'firebase/firestore';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';

let AgoraRTC: any;
if (typeof window !== 'undefined') {
  AgoraRTC = require('agora-rtc-sdk-ng');
}

const APP_ID = 'fd0e77a2c15f4c53af85276a8910ed8a';
const TOKEN = null;
const DEFAULT_ROOM_ID = '7JPPeJ2xdynNk8ybbnS7';
const DEFAULT_USER_NAME = 'Mouma';

export default function MeetingPage() {
  const [roomData, setRoomData] = useState<any>(null);
  const [joined, setJoined] = useState(false);
  const [cameraOn, setCameraOn] = useState(true);
  const [messages, setMessages] = useState<any[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const clientRef = useRef<any>(null);
  const localTrackRef = useRef<any>(null);
  const localVideoRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const fetchRoom = async () => {
      const ref = doc(db, 'rooms', DEFAULT_ROOM_ID);
      const snap = await getDoc(ref);
      if (snap.exists()) {
        setRoomData(snap.data());
      } else {
        await setDoc(ref, {
          roomName: 'New Room',
          createdAt: new Date(),
          participants: [],
        });
        setRoomData({ roomName: 'New Room', participants: [] });
      }
    };
    fetchRoom();
  }, []);

  useEffect(() => {
    const joinRoom = async () => {
      const ref = doc(db, 'rooms', DEFAULT_ROOM_ID);
      await updateDoc(ref, {
        participants: arrayUnion({ name: DEFAULT_USER_NAME, joinedAt: new Date() }),
      });
      setJoined(true);
    };
    joinRoom();
  }, []);

  useEffect(() => {
    const initAgora = async () => {
      if (!joined || typeof window === 'undefined' || !AgoraRTC) return;

      const client = AgoraRTC.createClient({ mode: 'rtc', codec: 'vp8' });
      clientRef.current = client;

      await client.join(APP_ID, DEFAULT_ROOM_ID, TOKEN || null, null);
      const localTrack = await AgoraRTC.createCameraVideoTrack();
      localTrackRef.current = localTrack;
      localTrack.play(localVideoRef.current!);
      await client.publish([localTrack]);
    };

    initAgora();

    return () => {
      if (clientRef.current) {
        clientRef.current.leave();
      }
    };
  }, [joined]);

  useEffect(() => {
    const q = query(collection(db, 'rooms', DEFAULT_ROOM_ID, 'messages'), orderBy('timestamp'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const msgs = snapshot.docs.map((doc) => doc.data());
      setMessages(msgs);
    });
    return () => unsubscribe();
  }, []);

  const toggleCamera = async () => {
    if (localTrackRef.current) {
      if (cameraOn) {
        localTrackRef.current.setEnabled(false);
      } else {
        localTrackRef.current.setEnabled(true);
      }
      setCameraOn(!cameraOn);
    }
  };

  const sendMessage = async () => {
    if (!newMessage.trim()) return;
    await addDoc(collection(db, 'rooms', DEFAULT_ROOM_ID, 'messages'), {
      sender: DEFAULT_USER_NAME,
      text: newMessage,
      timestamp: new Date(),
    });
    setNewMessage('');
  };

  if (!joined || !roomData) {
    return <div className="h-screen flex items-center justify-center">Loading...</div>;
  }

  return (
    <div className="flex flex-col h-screen">
      <div className="flex justify-between p-4 border-b items-center">
        <h1 className="text-lg font-semibold">{roomData?.roomName || 'Meeting Room'}</h1>
        <div className="flex items-center gap-2">
          <Button variant="outline" onClick={toggleCamera}>{cameraOn ? 'Turn Off Camera' : 'Turn On Camera'}</Button>
          <Button className="bg-red-500 text-white" onClick={async () => {if (clientRef.current) {
                                                                                await clientRef.current.leave();
                                                                                clientRef.current.removeAllListeners();
                                                                                clientRef.current = null;
                                                                              }

                                                                              const roomRef = doc(db, 'rooms', DEFAULT_ROOM_ID);
                                                                              await updateDoc(roomRef, {
                                                                                participants: roomData.participants.filter((p: any) => p.name !== DEFAULT_USER_NAME)
                                                                              });
                                                                              window.location.href = '/app'; // or wherever you want
                                                                            }}
                                                                              >End Meeting</Button>
        </div>
      </div>
      <div className="flex flex-1">
        <div className="flex-1">
          <div ref={localVideoRef} className="w-full h-full rounded" />
        </div>

        <div className="w-80 border-l p-4 flex flex-col">
          <h2 className="font-bold mb-2">Participants</h2>
          <div className="flex flex-col gap-2 overflow-auto">
            {roomData?.participants?.map((p: any, i: number) => (
              <div key={i} className="flex items-center gap-2">
                <Avatar><AvatarFallback>{p.name[0]}</AvatarFallback></Avatar>
                <p>{p.name}</p>
              </div>
            ))}
          </div>

          <h2 className="font-bold my-4">Chat</h2>
          <div className="flex-1 overflow-auto border rounded p-2 mb-2">
            {messages.map((msg, i) => (
              <div key={i} className="mb-1">
                <strong>{msg.sender}:</strong> {msg.text}
              </div>
            ))}
          </div>
          <div className="flex gap-2">
            <Input placeholder="Type a message..." value={newMessage} onChange={(e) => setNewMessage(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && sendMessage()}/>
            <Button onClick={sendMessage}>Send</Button>
          </div>
        </div>
      </div>
    </div>
  );
}